  '2cp358611w0': R`kuarsit`,
  '16xf38hbcna': R`Termasuk jenis batuan apakah ⟦0⟧?`,
  '1uvoqnvq97x': R`Batuan itu termasuk <b>⟦0⟧</b>.`,
  '1jm0619x2bl': R`Batuan metamorf apakah yang terbentuk jika ⟦0⟧ berubah karena panas dan tekanan?`,
  '6vsmzisfon': R`Panas dan tekanan mengubah ⟦0⟧ menjadi <b>⟦1⟧</b>.`,
