  'n6qnovqr0x': R`intan`,
  'dczjesd4v0': R`Pada skala Mohs, kekerasan ⟦0⟧ adalah ⟦1⟧ dan kekerasan ⟦2⟧ adalah ⟦3⟧. Pernyataan manakah yang benar?`,
  '5bvsq46t1e': R`⟦0⟧ dapat menggores ⟦1⟧`,
