  '2h45y6pp0w': R`Pelelehan`,
  '1hrtdrmodjf': R`Dalam siklus batuan, proses apakah yang mengubah ⟦0⟧ menjadi ⟦1⟧?`,
  '1vnep4vfqix': R`Mengapa granit memiliki kristal besar, sedangkan kristal basal sangat kecil?`,
  '1pzn9qkghqp': R`Granit mendingin perlahan jauh di bawah tanah; basal mendingin cepat di permukaan`,
  'tcas8zsxjw': R`Granit mendingin cepat di permukaan; basal mendingin perlahan di bawah tanah`,
  '26x2rrtdjdw': R`Granit lebih tua daripada basal`,
  'edjb75ocsy': R`Basal telah dihancurkan oleh pelapukan`,
  '2aahdymu0qw': R`Pendinginan yang lambat memberi waktu bagi kristal untuk tumbuh. Batuan intrusif mendingin perlahan di bawah tanah; lava ekstrusif mendingin dengan cepat.`,
  '14bko1y62dd': R`Mengapa batu apung sangat ringan sehingga dapat terapung?`,
  '17c8ul9ugtj': R`Batu apung penuh gelembung gas yang terperangkap ketika lava mendingin sangat cepat`,
  'bsiljwqnjy': R`Batu apung tidak mengandung mineral`,
  '1bgdi21610r': R`Batu apung terbuat dari kayu`,
  '1m0lxntlzbr': R`Batu apung adalah batuan sedimen dari cangkang`,
  '1lbort9583f': R`Batu apung terbentuk ketika lava yang kaya gas berbuih dan mendingin hampir seketika, sehingga menjadi batuan kaca yang penuh lubang.`,
  'eutjseb3aa': R`Batuan manakah yang paling mungkin mengandung fosil?`,
  '8f4snwo2f4': R`Batu gamping`,
  '28mugub64d6': R`Granit`,
  '1l8zezu0yd6': R`Basal`,
  '1stvw56hnol': R`Obsidian`,
  'mz4mbq7u18': R`Fosil terawetkan dalam batuan sedimen seperti batu gamping dan serpih; panas batuan beku memusnahkannya.`,
  '1k9gey8cx55': R`Apa yang dimaksud dengan mineral?`,
  '7bkulufeg9': R`Zat padat alami dengan susunan dan struktur kristal tertentu`,
  '1j91df0912d': R`Campuran batuan apa saja`,
  '1zpab250qra': R`Apa saja yang digali dari dalam tanah`,
  '2f3x477yk3g': R`Batuan yang terbentuk dari cangkang`,
  '6urlzqbdk1': R`Mineral seperti kuarsa memiliki rumus kimia yang tetap dan struktur kristal yang teratur; batuan tersusun atas mineral-mineral.`,
  '4k11rt9sl2': R`
<p><b>Vulkanisme</b> mencakup semua peristiwa naiknya magma, batuan cair dari dalam Bumi. Magma yang membeku di bawah permukaan membentuk <b>intrusi</b>: <b>batolit</b> yang sangat besar, <b>lakolit</b> yang berbentuk lensa, <b>sill</b> yang mendatar di antara lapisan batuan, dan <b>gang</b> (dike) yang tegak memotong lapisan. Magma yang mencapai permukaan keluar sebagai <b>lava</b>.</p>
⟦0⟧
⟦1⟧
⟦2⟧
<h3>Bahaya dan manfaat</h3>
<p>Bahayanya antara lain <b>awan panas</b> (aliran piroklastik, "wedhus gembel"), <b>lahar</b> (aliran lumpur vulkanik, sering setelah hujan lebat), hujan abu, aliran lava, gas beracun, dan tsunami. Manfaatnya antara lain tanah yang subur, energi panas bumi, pasir dan batu bangunan, bahan tambang, dan pariwisata.</p>
⟦3⟧`,
  '2bxasx78q6n': R`Dapur magma`,
  '1wn04dhyacx': R`Diatrema (pipa kepundan)`,
  '1pd5obyd4ya': R`Kawah`,
