  '12re0iycihi': R`kerucut kecil dan curam dari material lepas`,
  '7qc5gue3i9': R`Anak Krakatau pada tahun-tahun awalnya`,
  'd3zq0btsg': R`Kaldera`,
  '2dadsir4rcl': R`cekungan besar yang tersisa ketika gunung api runtuh setelah dapur magmanya kosong`,
  'tmk5qxqo1j': R`Toba, Tengger (Bromo)`,
  '14ed5xhb2ol': R`<p><b>Eksplosif atau efusif?</b> Magma yang kental, kaya gas, dan kaya silika (andesit, riolit) memerangkap gas lalu meledak; basal yang encer dan miskin silika melepaskan gas dan mengalir dengan tenang. <b>Indeks Letusan Gunung Api</b> (VEI) berkisar dari 0 sampai 8, dan setiap kenaikan satu tingkat berarti material yang dikeluarkan sekitar sepuluh kali lebih banyak. Letusan Tambora (1815) ber-VEI 7.</p>`,
  '29z8uf3dca2': R`<p>Tingkat status gunung api di Indonesia, dari rendah ke tinggi: <b>Normal</b> (level I), <b>Waspada</b> (II), <b>Siaga</b> (III), dan <b>Awas</b> (IV: warga di zona bahaya diungsikan).</p>`,
  'l0l6m3fxkh': R`Setiap kenaikan satu tingkat pada Indeks Letusan Gunung Api berarti material yang dikeluarkan sekitar sepuluh kali lebih banyak. Kira-kira berapa kali lebih banyak material yang dikeluarkan letusan VEI ⟦0⟧ dibandingkan letusan VEI ⟦1⟧?`,
  '1zw71o6j03o': R`$10^{⟦0⟧ - ⟦1⟧} = 10^{⟦2⟧} = ⟦3⟧$ kali.`,
  '2c2307paqvs': R`Awan abu tertiup ke arah sebuah kota yang berjarak ⟦0⟧ oleh angin berkecepatan ⟦1⟧. Kira-kira berapa jam lagi abu itu akan tiba?`,
  '84sjde5hv3': R`$⟦0⟧\,\mathrm{m/s} = ⟦1⟧\,\mathrm{km/jam}$, jadi $t = \frac{⟦2⟧}{⟦3⟧} = ⟦4⟧$.`,
  '26xauedyus6': R`Gunung api strato`,
