  'kpf9jgy47f': R`Penampang sebuah gunung api`,
  '1g4spjinnsi': R`Kerucut berlapis yang curam adalah gunung api strato; kubah yang lebar dan landai adalah gunung api perisai; timbunan kecil yang curam adalah kerucut sinder; cekungan runtuhan yang luas adalah kaldera. Ini adalah <b>⟦0⟧</b>.`,
