  'xuvexmrtw2': R`Abu vulkanik lapuk menjadi tanah yang subur; itulah sebabnya lereng gunung api di Jawa padat dengan lahan pertanian. Energi panas bumi dan pariwisata adalah manfaat lainnya.`,
