  'yozt8fx4z9': R`
<p><b>Tanah</b> adalah lapisan teratas daratan yang gembur, campuran partikel mineral, bahan organik (humus), air, dan udara, tempat tumbuhan tumbuh. Tanah terbentuk sangat lambat, sering kali satu sentimeter dalam seratus tahun atau lebih, sehingga mudah hilang dan sulit digantikan.</p>
⟦0⟧
⟦1⟧
<h3>Tekstur</h3>
<p>Butir-butir tanah dikelompokkan menurut ukurannya: <b>pasir</b> (0,05–2 mm, terasa kasar, cepat meloloskan air), <b>debu</b> (0,002–0,05 mm, terasa halus), dan <b>liat</b> (kurang dari 0,002 mm, lengket, menahan air dan unsur hara). Perpaduan ketiganya menentukan <b>tekstur</b>, yang dibaca pada segitiga tekstur. <b>Lempung</b>, dengan campuran yang seimbang, paling baik untuk sebagian besar tanaman.</p>
⟦2⟧
⟦3⟧
⟦4⟧`,
