  '18vrcwaxvwu': R`Pengertian`,
  'nnavwjchwb': R`absolut (koordinat, misalnya 6°LS 106°BT) atau relatif (terhadap tempat lain, misalnya dekat pelabuhan)`,
  'zb4t99ghwh': R`seberapa jauh tempat-tempat terpisah, dalam kilometer, waktu tempuh, atau biaya`,
