  '2bldow8cauj': R`bentuk permukaan lahan: dataran, perbukitan, pegunungan, pantai`,
  '2eq9uk6wd7t': R`pemusatan kegiatan sejenis di satu wilayah, misalnya kawasan industri`,
  '1mlmabbr72c': R`seberapa berguna suatu tempat, yang bisa berbeda bagi setiap orang`,
  '1nvenegrajg': R`tempat-tempat yang saling bergantung dan saling memengaruhi, misalnya desa memasok bahan pangan ke kota`,
  'r62wdsnch6': R`setiap wilayah memiliki perpaduan ciri khas yang membedakannya dari wilayah lain`,
  '280sfqdwtyq': R`hubungan antarfenomena di suatu wilayah, misalnya penggundulan hutan dan banjir di hilir`,
  '2131rmdvvgn': R`<p><b>Empat prinsip.</b> <i>Persebaran</i>: fenomena tersebar tidak merata di permukaan Bumi. <i>Interelasi</i>: fenomena saling memengaruhi. <i>Deskripsi</i>: pola dan penyebabnya dijelaskan dengan kata-kata, peta, tabel, dan grafik. <i>Korologi</i>: suatu fenomena dikaji bersama segala sesuatu di sekitarnya dalam wilayahnya.</p><p><b>Tiga pendekatan.</b> Pendekatan <i>keruangan</i> mengkaji di mana sesuatu berada dan mengapa. Pendekatan <i>kelingkungan</i> (ekologi) mengkaji hubungan manusia dengan lingkungannya. Pendekatan <i>kompleks wilayah</i> menggabungkan keduanya untuk membandingkan wilayah secara utuh.</p>`,
  '215l8o2u06v': R`<p>Untuk menentukan konsep dalam soal, cari gagasan kuncinya: "berkumpul di satu tempat" adalah aglomerasi, "mudah dicapai" adalah keterjangkauan, "satu tempat memasok tempat lain" adalah interaksi, "bentuk lahan" adalah morfologi.</p>`,
  '1eyzaejtlp7': R`Banyak pabrik tekstil berkumpul di satu kawasan industri.`,
  'gfcry2nn0t': R`Petani di pegunungan mengirim sayuran ke kota, dan kota mengirim barang-barang hasil industri kembali ke desa.`,
  'gffwossn9w': R`Sebuah desa sulit dicapai karena tidak ada jalan dan tidak ada jembatan di atas sungai.`,
  'rk9wq8afwi': R`Jakarta terletak di sekitar 6°LS dan 107°BT.`,
  '26azzv81v9o': R`Pasar berjarak 15 menit naik sepeda motor dari desa.`,
  'wy199uusl9': R`Rumah-rumah di sebuah lembah dibangun berjajar di sepanjang tepi sungai.`,
  'kf011fwuo8': R`Wilayah itu berupa dataran rendah yang dikelilingi perbukitan terjal.`,
  'qe9j3g8edp': R`Bagi peselancar, pantai berombak besar sangat berharga, tetapi bagi nelayan pantai itu berbahaya.`,
  'mrgx6aw7xu': R`Dataran tinggi ditanami teh dan sayuran, sedangkan dataran rendah ditanami padi.`,
