  'jvtfg7zsvy': R`Bengkel para perajin perak terpusat di satu kampung di kota itu.`,
  'wese6fjw25': R`Konsep esensial geografi manakah yang digambarkan pernyataan ini? <i>⟦0⟧</i>`,
  '1xwai6t55uq': R`Gagasan kunci pernyataan itu adalah <b>⟦0⟧</b>.`,
  '1e98kt6q3z': R`Menjelaskan mengapa tanah longsor sering terjadi di suatu wilayah dengan mengkaji lereng, tanah, dan curah hujannya sekaligus`,
  '2ewusy1rh8g': R`Interelasi`,
  'wdm392gyiv': R`Menunjukkan pada peta bahwa gunung api di Indonesia tersebar membentuk busur`,
  '115owsb7jcv': R`Persebaran`,
  'oeke05wg02': R`Menyajikan data panen padi dengan grafik dan penjelasan tertulis`,
  '1ls4al65qvg': R`Deskripsi`,
  '6pljq0ucir': R`Mengkaji banjir dengan melihat curah hujan, penggunaan lahan, dan jaringan sungai di seluruh wilayah`,
  'uzb9pcirp': R`Korologi`,
  '1xsdvp5febo': R`Prinsip geografi manakah yang digunakan? <i>⟦0⟧</i>`,
  '1h2m0974kje': R`Ini adalah prinsip <b>⟦0⟧</b>: ⟦1⟧`,
  'l02tfh9bur': R`fenomena tersebar tidak merata di ruang muka Bumi.`,
