  '7eqlsagzfx': R`berisi ionosfer yang memantulkan gelombang radio; aurora; Stasiun Luar Angkasa Internasional mengorbit di sini`,
  'j97aw81r6f': R`<p><b>Suhu di troposfer.</b> Udara dipanaskan dari bawah oleh permukaan tanah, sehingga makin tinggi makin dingin, rata-rata <b>6,5 °C setiap kilometer</b> (laju penurunan suhu lingkungan):</p><p>$$T_h = T_0 - 6{,}5\,h$$</p><p>dengan $h$ dalam km. <b>Tekanan udara</b> turun jauh lebih cepat: kira-kira menjadi separuhnya setiap naik 5,5 km, dari sekitar 1.013 hPa di permukaan laut.</p>`,
  '1vimk2zaizh': R`<p><b>Lapisan ozon</b> menipis akibat klorofluorokarbon (CFC) yang dulu dipakai di kulkas dan kaleng semprot. Protokol Montreal (1987) melarangnya, dan lubang ozon di atas Antarktika perlahan pulih.</p>`,
