  '17w500xnn3p': R`<p>$$T = 26{,}3 - 0{,}6 \times \frac{h}{100}$$</p><p>dengan $T$ suhu rata-rata tahunan dalam °C, $26{,}3$ °C suhu rata-rata di permukaan laut di Indonesia, dan $h$ ketinggian dalam meter. Antara dua tempat: $T_B = T_A - 0{,}6 \times \frac{h_B - h_A}{100}$.</p>`,
