  'i89nai92ej': R`<p>$$RH = \frac{\text{uap air sebenarnya}}{\text{uap air maksimum}} \times 100\%$$</p><p>Pada 100% udara jenuh dan uap air mengembun menjadi embun, kabut atau awan. Udara hangat dapat menampung lebih banyak uap air daripada udara dingin.</p>`,
  'i9slsz3j8p': R`<p>BMKG menghitung <b>suhu rata-rata harian</b> dari pengamatan pukul 07.00, 13.00 dan 18.00: $T = \frac{2\,T_{07} + T_{13} + T_{18}}{4}$. Pada peta cuaca, garis menghubungkan tempat-tempat yang nilainya sama: <b>isoterm</b> (suhu), <b>isobar</b> (tekanan udara), <b>isohiet</b> (curah hujan), <b>isohel</b> (penyinaran matahari) dan <b>isoneph</b> (tutupan awan).</p>`,
  '3usp07e8x0': R`Dengan rumus Braak, berapa suhu rata-rata tahunan sebuah kota di Indonesia yang terletak ⟦0⟧ di atas permukaan laut?⟦1⟧`,
  '10ubro018cr': R`Sebuah gunung dengan satu kota ditandai di lerengnya`,
  'u3qgsn28lx': R`$T = 26{,}3 - 0{,}6 \times \frac{⟦0⟧}{100} = 26{,}3 - ⟦1⟧ = ⟦2⟧$.`,
  '1b52njcpgzj': R`Suatu tempat di Indonesia memiliki suhu rata-rata tahunan ⟦0⟧. Dengan rumus Braak, kira-kira berapa ketinggiannya di atas permukaan laut?`,
  '1jhllysec64': R`$⟦0⟧ = 26{,}3 - 0{,}6 \times \frac{h}{100}$, jadi $h = \frac{26{,}3 - ⟦1⟧}{0{,}6} \times 100 = ⟦2⟧$.`,
  '2ecqtvenbh9': R`Kota A berada ⟦0⟧ di atas permukaan laut dan suhunya ⟦1⟧. Kota B di gunung yang sama berada pada ketinggian ⟦2⟧. Jika suhu turun 0,6 °C setiap 100 m, berapa suhu di kota B?`,
  '2eym35nibpq': R`Selisih ketinggiannya ⟦0⟧, jadi suhu turun $0{,}6 \times ⟦1⟧ = ⟦2⟧$ °C: $T_B = ⟦3⟧ - ⟦4⟧ = ⟦5⟧$.`,
  '18t0ku09gx5': R`Udara pada suhu tertentu dapat menampung paling banyak ⟦0⟧ uap air. Kenyataannya udara itu mengandung ⟦1⟧. Berapa kelembapan relatifnya?`,
  'oky7cxz6ad': R`Sebuah stasiun cuaca mencatat ⟦0⟧ pada pukul 07.00, ⟦1⟧ pada pukul 13.00 dan ⟦2⟧ pada pukul 18.00. Dengan $T = \frac{2\,T_{07} + T_{13} + T_{18}}{4}$, berapa suhu rata-rata hariannya?`,
