  '25zv0hk3d3': R`dari Asia: basah, musim hujan`,
  'udu1gb4hhc': R`Peta Indonesia dengan angin muson barat yang bertiup dari Asia ke arah Australia`,
  'lnbo5hunyf': R`Muson barat, kira-kira Oktober sampai April: angin dari Asia melintasi Samudra Pasifik dan Laut Cina Selatan, membawa banyak uap air dan mendatangkan musim hujan.`,
  '2ag7prxolgw': R`dari Australia: musim kemarau`,
  '4q4ozipidg': R`Peta Indonesia dengan angin muson timur yang bertiup dari Australia ke arah Asia`,
  'mkdhffjmev': R`Muson timur, kira-kira April sampai Oktober: angin kering dari gurun Australia hanya melintasi laut yang sempit dan mendatangkan musim kemarau.`,
  '2c08nm814s8': R`Angin laut (siang)`,
  '1z3lowl9the': R`Darat`,
  'qbtivhor03': R`udara hangat naik`,
  '1xw6qyvg710': R`udara dingin turun`,
  '1yh5utd9s0': R`Angin laut pada siang hari: udara hangat naik di atas daratan dan udara dingin bertiup dari laut ke darat`,
  '2d3awkbgh5c': R`Pada siang hari daratan lebih cepat panas daripada laut, sehingga angin bertiup dari laut ke darat. Nelayan pulang dengan angin ini pada sore hari.`,
  '17pkwktkh4u': R`Angin darat (malam)`,
  '29eqdt51bhd': R`Angin darat pada malam hari: udara naik di atas laut yang lebih hangat dan angin bertiup dari darat ke laut`,
  '1iybj6u95hw': R`Pada malam hari daratan lebih cepat dingin, sehingga arah angin berbalik. Nelayan berangkat melaut dengan angin ini.`,
  '1o0dq7667sa': R`angin lembap`,
  '1bqzned6fan': R`mendingin, berawan, hujan`,
  '31ehnpv51q': R`angin kering dan panas`,
  'nuigaw7jru': R`Lereng bawah angin`,
  '28vm7d2q8r9': R`Lereng atas angin`,
  '183yjkbo7ow': R`Angin fohn: udara lembap naik di lereng atas angin dan turun hujan, lalu menuruni lereng bawah angin sebagai angin kering dan panas`,
  'rw87mthh0r': R`Angin fohn. Udara kehilangan uap airnya sebagai hujan di lereng atas angin, lalu cepat memanas ketika turun di lereng bawah angin.`,
  '19lqzs585ya': R`<p>Udara lembap yang naik mendingin sekitar <b>0,6 °C per 100 m</b> (uap air yang mengembun melepaskan panas), tetapi udara kering yang turun memanas sekitar <b>1 °C per 100 m</b>, sehingga udara di kaki lereng bawah angin lebih panas daripada saat awal. Angin fohn di Indonesia memiliki nama lokal: <i>Bohorok</i> (Deli, Sumatra Utara), <i>Kumbang</i> (Cirebon dan Tegal), <i>Gending</i> (Pasuruan dan Probolinggo), <i>Brubu</i> (Makassar) dan <i>Wambraw</i> (Biak). Angin lembah bertiup naik ke lereng pada siang hari dan angin gunung turun pada malam hari.</p>`,
  '1ccsziflj8i': R`Tempat A memiliki tekanan udara ⟦0⟧ dan tempat B, yang berjarak ⟦1⟧, ⟦2⟧. Berapa gradien barometriknya, dalam hPa per 100 km? Ke arah mana angin mulai bertiup?`,
  '1nqdc7r5vix': R`$\frac{⟦0⟧ - ⟦1⟧}{⟦2⟧} \times 100 = ⟦3⟧$ hPa per 100 km. Angin bertiup dari A (tekanan tinggi) ke B (tekanan rendah), dibelokkan oleh gaya Coriolis.`,
  'r184umxyvj': R`Udara lembap bersuhu ⟦0⟧ naik dari permukaan laut melewati gunung setinggi ⟦1⟧ dan mendingin 0,6 °C per 100 m. Setelah uap airnya jatuh sebagai hujan, udara itu turun di sisi lain sampai ke permukaan laut dan memanas 1 °C per 100 m. Berapa suhunya di kaki lereng bawah angin?⟦2⟧`,
  '2bfzjpkxvpd': R`Angin fohn melintasi gunung`,
  'txj7rsqilf': R`Di puncak: $⟦0⟧ - 0{,}6 \times ⟦1⟧ = ⟦2⟧$ °C. Turun di sisi lain: $⟦3⟧ + 1 \times ⟦4⟧ = ⟦5⟧$, lebih panas daripada saat awal. Inilah angin fohn.`,
  '21jqezw8l75': R`Pada siang hari, udara sejuk bertiup dari laut ke arah darat.`,
  '2dlqi7ku76p': R`Angin laut`,
  '1mvul1q70w9': R`Pada malam hari, udara bertiup dari darat ke laut.`,
  '26iownlm6k6': R`Angin darat`,
  '1y7kacznip5': R`Pada siang hari, udara mengalir dari lembah naik ke lereng gunung.`,
  'wjrlrb980o': R`Angin lembah`,
  '28o0tfibqvf': R`Pada malam hari, udara dingin mengalir menuruni lereng ke lembah.`,
  'dydmiww6xb': R`Angin gunung`,
  '1no3s3t3p9b': R`Angin kering dan panas bertiup menuruni lereng bawah angin suatu pegunungan.`,
  '1zp2cahetot': R`Angin fohn`,
  '1cka2jgequn': R`Angin lokal apakah ini? <i>⟦0⟧</i>`,
  '1h2ahlcxwr3': R`Bohorok`,
  'sf7euwm2jw': R`Deli, Sumatra Utara`,
