  '3dl4rcklvr': R`Angin fohn yang disebut <i>⟦0⟧</i> bertiup di daerah mana?`,
  '1npep076ljl': R`Angin ⟦0⟧ bertiup di <b>⟦1⟧</b>.`,
  '1rpqn1mk1i2': R`Perhatikan peta. Angin muson apa yang ditunjukkan, dan musim apa yang dibawanya ke sebagian besar Indonesia?⟦0⟧`,
  'ovq3z8xtlu': R`dari Asia`,
