  '1lwsi17pmsc': R`Muson barat: musim kemarau`,
  '1evo1ehuntj': R`Muson timur: musim hujan`,
  '1upa75iu4dw': R`Angin dari Asia (tekanan tinggi saat musim dingin di belahan utara) melintasi laut yang luas, membawa uap air dan mendatangkan hujan: muson barat, kira-kira Oktober sampai April.`,
  '13dhg0v33sv': R`Angin dari Australia (tekanan tinggi saat musim dingin di belahan selatan) hanya melintasi sedikit laut dan tetap kering: muson timur, kira-kira April sampai Oktober.`,
