  '1uspe7sd5fy': R`Udara yang naik di khatulistiwa turun di sekitar lintang 30°, memanas dan mengering saat turun: Gurun Sahara, Arab dan Australia terletak di sini.`,
  '19zvq4h6xot': R`Apa itu ITCZ?`,
  '1u6z74nbw8l': R`Sabuk tekanan rendah dekat khatulistiwa tempat angin pasat bertemu`,
  'ktbjnryxea': R`Sabuk tekanan tinggi di lintang 30°`,
  '272n1w0s1q3': R`Arus laut dingin`,
  '1hfgql4vwtr': R`Salah satu lapisan atmosfer`,
  '1l7bu5afkqh': R`Daerah Konvergensi Antartropis (ITCZ) adalah tempat angin pasat dari kedua belahan bumi bertemu dan udara naik, sehingga turun hujan lebat. Letaknya mengikuti posisi Matahari tegak lurus.`,
  '26jcoo4im4w': R`Pada peta cuaca, isobar-isobarnya sangat rapat. Apa artinya?`,
