  '23h1lelg9h3': R`Isobar yang rapat berarti gradien barometrik besar, yang menimbulkan angin kencang.`,
  '1is5adbzdle': R`Mengapa pada siang hari angin bertiup dari laut ke darat?`,
  '1amkj2jbr0a': R`Daratan lebih cepat panas, sehingga udaranya naik dan tekanannya lebih rendah`,
  '580fonsgfm': R`Pada siang hari laut lebih panas daripada daratan`,
