  'qfb87fzljo': R`Pasang surut mendorong udara`,
  '9jbd74ujos': R`Daratan lebih cepat panas daripada air; udara hangat di atas daratan naik, dan udara yang lebih sejuk dari laut bergerak menggantikannya.`,
