  'sjb16latpr': R`Hujan orografis`,
  'u9epyv13ay': R`Hujan frontal`,
  '1ok78fudifk': R`Jenis hujan apa yang ditunjukkan diagram?⟦0⟧`,
  'g334l1oxt9': R`Tanah dipanaskan Matahari`,
  '2b33y5xohsg': R`Udara dingin`,
  '2b4fx2ib8ho': R`Udara hangat`,
  '8k8ygjbvy7': R`Diagram udara yang naik dan membentuk hujan`,
  'tlg3eei3qh': R`Hujan siklonal`,
  'kl4fuanide': R`Pemanasan kuat membuat udara naik: hujan <b>konveksi</b>.`,
  '2dy794dy6h': R`Gunung memaksa udara naik: hujan <b>orografis</b>, dengan bayangan hujan di baliknya.`,
  'dqft2j7rds': R`Udara hangat naik di atas udara dingin: hujan <b>frontal</b>.`,
  '2c8ebt3g7ou': R`Apa yang harus terjadi pada udara yang naik sebelum awan dapat terbentuk?`,
  'dau79ewdmi': R`Udara harus mendingin sampai titik embunnya`,
  '2cyfqumofgw': R`Udara harus memanas`,
