  'mi8nq2roeg': R`<p><b>Membaca klimograf.</b> <i>Amplitudo suhu tahunan</i> adalah suhu bulan terpanas dikurangi suhu bulan terdingin. <i>Curah hujan tahunan</i> adalah jumlah kedua belas batang. Di dekat khatulistiwa amplitudonya sangat kecil (1–3 °C), sehingga musim ditentukan oleh hujan, bukan oleh suhu.</p>`,
  'i08k9en7ub': R`<p><b>Oldeman</b> mengklasifikasikan iklim Indonesia untuk pertanian dengan menghitung <b>bulan basah berturut-turut</b> (lebih dari 200 mm, cukup untuk padi) dan bulan kering (kurang dari 100 mm). Zona A memiliki lebih dari 9 bulan basah berturut-turut, B 7–9, C 5–6, D 3–4 dan E kurang dari 3.</p>`,
  'tyakgmy4hn': R`Golongan iklim Köppen apa yang ditunjukkan klimograf ini?⟦0⟧`,
  'u01vun8v9u': R`Klimograf dengan batang curah hujan bulanan dan garis suhu`,
  'lnj8ztieq9': R`Bulan terdingin ⟦0⟧ °C dan terpanas ⟦1⟧ °C, dengan curah hujan ⟦2⟧ mm setahun. Itu sesuai dengan golongan <b>⟦3⟧</b>.`,
  '1fo6w4lsmz2': R`Suhu rata-rata bulanan (°C) di sebuah stasiun, Januari sampai Desember: ⟦0⟧. Berapa amplitudo suhu tahunannya?`,
