  '2mqni2qsoa': R`Klimograf stasiun yang sama`,
  '1wjq1yjdbz4': R`Jumlahnya ⟦0⟧, rata-rata ⟦1⟧ per bulan.`,
  '2aig8dqa8cj': R`Suatu tempat terletak pada lintang ⟦0⟧°. Termasuk zona iklim matahari apa?`,
  'wayg7wudw0': R`Batasnya ⟦0⟧°, 40° dan ⟦1⟧°, jadi ⟦2⟧° termasuk zona <b>⟦3⟧</b>.`,
  '4zmavolua2': R`Suatu tempat yang cukup hujan untuk pepohonan memiliki bulan terdingin ⟦0⟧ dan bulan terpanas ⟦1⟧. Termasuk golongan Köppen apa?`,
  '15941vb9wef': R`A: bulan terdingin minimal 18 °C. C: bulan terdingin antara −3 dan 18 °C. D: bulan terdingin di bawah −3 °C dan terpanas di atas 10 °C. E: bulan terpanas di bawah 10 °C. Jadi ini golongan <b>⟦0⟧</b>.`,
