  '23d8tu3f7wr': R`Efek rumah kaca. Tanpa efek ini suhu rata-rata Bumi sekitar −18 °C, bukan +15 °C; dengan lebih banyak gas rumah kaca, lebih banyak panas yang tertahan.`,
