  'htotic0jj5': R`<p><b>El Niño dan La Niña</b> (ENSO) adalah perubahan alami di Samudra Pasifik. Saat <b>El Niño</b> angin pasat melemah, air hangat bergerak ke timur menuju Amerika Selatan dan Indonesia mendapat hujan <i>lebih sedikit</i>: kekeringan dan kebakaran. Saat <b>La Niña</b> angin pasat menguat, air hangat menumpuk di dekat Indonesia dan hujan <i>bertambah</i>: banjir. Perubahan iklim dapat membuat perubahan ini makin ekstrem.</p>`,
  'lxq5aciuha': R`<p><b>Mitigasi</b> mengurangi penyebabnya: energi terbarukan, hemat energi, melindungi hutan dan gambut, transportasi umum. <b>Adaptasi</b> menyesuaikan diri dengan dampaknya: tanggul laut dan mangrove, tanaman tahan kekeringan, sistem peringatan dini. <b>Protokol Kyoto</b> (1997) dan <b>Perjanjian Paris</b> (2015), yang bertujuan menjaga pemanasan jauh di bawah 2 °C dan sebaiknya 1,5 °C, adalah perjanjian utamanya.</p>`,
  '1fxfi3sthvv': R`Kadar karbon dioksida di udara adalah ⟦0⟧ pada tahun ⟦1⟧ dan ⟦2⟧ pada tahun ⟦3⟧. Berapa rata-rata kenaikannya per tahun, dalam ppm?`,
  '21csf75ztzt': R`$\frac{⟦0⟧ - ⟦1⟧}{⟦2⟧ - ⟦3⟧} = \frac{⟦4⟧}{⟦5⟧} = ⟦6⟧$ ppm per tahun.`,
  '16wrjpte9mh': R`Sebelum zaman industri udara mengandung sekitar ⟦0⟧ CO₂. Berapa persen kenaikannya ketika kadarnya mencapai ⟦1⟧?`,
  '1tchzuvpza7': R`Muka air laut naik sekitar ⟦0⟧ per tahun. Jika lajunya tetap, berapa sentimeter kenaikannya dalam ⟦1⟧ tahun?`,
  'mj0hdka82y': R`$⟦0⟧ \times ⟦1⟧ = ⟦2⟧$ mm $= ⟦3⟧$.`,
  '1tj6dcn9vit': R`Bacalah grafik. Kira-kira berapa kadar CO₂ di udara pada tahun ⟦0⟧?⟦1⟧`,
