  '2atjo419mee': R`seluruh air`,
  '1z0uug9cfzg': R`Diagram donat air di Bumi: 97,5 persen di lautan, 1,7 persen es, 0,76 persen air tanah dan 0,04 persen di danau, sungai, udara dan tanah`,
