  'kmra6tro4n': R`infiltrasi`,
  '2enbck5y9tb': R`aliran air tanah`,
  '6oy1g5m831': R`Siklus air: air menguap dari laut, mengembun menjadi awan yang terbawa ke daratan, turun sebagai hujan, lalu kembali ke laut melalui sungai dan air tanah`,
  '4jck4nxro1': R`Proses-proses utama dalam siklus air.`,
  '137ld4xmfi': R`Proses`,
  '26x986njc7f': R`Yang terjadi`,
  '9wxdgjsdsj': R`Evaporasi`,
  '1lmip2zm7qg': R`air berubah menjadi uap, terutama dari laut`,
  '1l4ap4ywvgp': R`Transpirasi`,
  '1j7ubldi2im': R`tumbuhan melepaskan uap air melalui daunnya (bersama evaporasi disebut evapotranspirasi)`,
  'agtsappv28': R`Kondensasi`,
  'raoxmuc2m6': R`uap air mendingin dan menjadi butir-butir awan`,
  '1ow3pqs5onz': R`Adveksi`,
  '1j0aq431lim': R`angin membawa awan dari laut ke daratan`,
  's5auvpkg82': R`Presipitasi`,
  '27hi7bf35k6': R`air jatuh sebagai hujan, salju atau hujan es`,
  '1dbt80kmwml': R`Infiltrasi`,
  'f19xz4m5gi': R`air meresap ke dalam tanah`,
  '18h3mct1a30': R`Perkolasi`,
  '1xvr3l8rkca': R`air bergerak lebih dalam sampai ke air tanah`,
  '1h5t6s06tyv': R`Limpasan`,
  'eb7ippihia': R`air mengalir di permukaan ke sungai lalu kembali ke laut`,
  '14ziy9tjt2p': R`<p><b>Neraca air</b> suatu daerah aliran sungai selama setahun: hujan yang turun pasti pergi ke suatu tempat,</p><p>$$P = E + R \pm \Delta S$$</p><p>dengan $P$ curah hujan, $E$ evapotranspirasi, $R$ limpasan dan $\Delta S$ perubahan simpanan (tanah dan air tanah). <b>Koefisien limpasan</b> $C = \frac{R}{P}$ menyatakan bagian hujan yang menjadi limpasan: sekitar 0,1–0,3 untuk hutan, 0,7–0,95 untuk atap dan jalan.</p>`,
  'fsd66pyhtj': R`<p>Penebangan hutan dan pembetonan lahan menaikkan $C$: lebih sedikit air yang meresap untuk mengisi air tanah, dan lebih banyak yang langsung mengalir ke sungai, sehingga terjadi banjir pada musim hujan dan sumur kering pada musim kemarau. Lubang biopori, sumur resapan dan ruang terbuka hijau membantu air meresap kembali.</p>`,
  '14sjedl284t': R`Suatu daerah aliran sungai menerima hujan ⟦0⟧ dalam setahun. Sebanyak ⟦1⟧ kembali ke udara melalui evapotranspirasi dan simpanan di tanah serta air tanah naik ⟦2⟧. Berapa yang menjadi limpasan?`,
  'ouxzfsr5i6': R`Hujan badai sebesar ⟦0⟧ turun di suatu daerah, dan ⟦1⟧ di antaranya menjadi limpasan. Berapa koefisien limpasan $C$?`,
  '1hyfl7vja1u': R`Nilainya tinggi: banyak permukaan yang diperkeras atau gundul.`,
  '1j3vws4o04j': R`Nilainya rendah: sebagian besar air meresap, seperti di hutan.`,
  '1ulgq1ymap5': R`lapangan parkir beraspal`,
  'd0qn8jusxy': R`hutan`,
  '1mfstec5y4h': R`kompleks perumahan`,
  '16cazfkq6xu': R`lahan pertanian`,
  '23o0x3e77hc': R`Hujan ⟦0⟧ turun di ⟦1⟧ seluas ⟦2⟧ dengan koefisien limpasan ⟦3⟧. Berapa meter kubik air yang menjadi limpasan? (1 ha = 10.000 m²)`,
  '1pad7dzr30y': R`Volume hujan $= ⟦0⟧\,\mathrm{m} \times ⟦1⟧\,\mathrm{m^2} = ⟦2⟧\,\mathrm{m^3}$; limpasan $= ⟦3⟧ \times ⟦4⟧ = ⟦5⟧$.`,
  'a72nh8bcwk': R`Uap air mendingin tinggi di udara dan berubah menjadi butir-butir awan.`,
  '1ypljc7lspx': R`Matahari memanaskan laut dan air berubah menjadi uap.`,
