  '2avhi7785ng': R`Proses siklus air apakah ini? <i>⟦0⟧</i>`,
  't0huuhyjj5': R`Air laut menguap, mengembun, lalu turun hujan kembali di laut.`,
  '1w2afgjw3tw': R`Siklus pendek`,
  'dmmle7h4ra': R`Awan dari laut terbawa angin ke daratan, turun hujan, dan sungai membawa airnya kembali.`,
  '1k7mtasuuhu': R`Siklus sedang`,
  '1j6u9c3mflq': R`Uap air jatuh sebagai salju di pegunungan tinggi dan kembali perlahan melalui gletser dan sungai.`,
  '1xbdplv8tun': R`Siklus panjang`,
  '29bl6q1xjow': R`Siklus air yang mana yang dijelaskan? <i>⟦0⟧</i>`,
  'zs9wtims9x': R`Ini adalah <b>⟦0⟧</b>.`,
  'yg79gub78c': R`Kira-kira berapa bagian seluruh air di Bumi yang merupakan air tawar?`,
