  '1oddlow95uj': R`Sekitar 97,5% adalah air asin di lautan; sisanya 2,5% air tawar, sebagian besar berupa es dan air tanah.`,
  '1oorwmct3fv': R`Apa yang menggerakkan siklus air?`,
