  '1okr36ppncf': R`Panas dari inti Bumi`,
  '223w05zud0b': R`Sinar matahari menguapkan air dan mengangkatnya ke udara; gravitasi menurunkannya sebagai hujan dan membuatnya mengalir ke tempat yang lebih rendah.`,
  '1l12fiyswz0': R`Apa yang terjadi pada siklus air jika hutan diganti menjadi kota?`,
  't0kyh490ib': R`Infiltrasi berkurang dan limpasan bertambah`,
  '140d88s66hv': R`Infiltrasi bertambah dan limpasan berkurang`,
  'om6csbkazy': R`Transpirasi bertambah`,
  'mmt5uahm2w': R`Tidak ada perubahan`,
  '2c2ynh67yus': R`Atap dan jalan menghalangi air meresap, sehingga lebih banyak air yang cepat mengalir ke sungai dan lebih sedikit yang mengisi air tanah.`,
  '1qhqf5m1xyn': R`Manakah cara membantu air hujan meresap kembali ke tanah di kota?`,
  '1u9qpk5adt7': R`Lubang biopori dan sumur resapan`,
  '1eqmd97l07x': R`Membeton halaman`,
  '26mapyvbxcr': R`Meluruskan sungai`,
  '29m2pp8bvm8': R`Menebang pohon di tepi jalan`,
  '28malr58jk9': R`Lubang biopori, sumur resapan dan ruang terbuka hijau menambah infiltrasi dan mengurangi limpasan.`,
  '113mtipxyag': R`
<p><b>Daerah aliran sungai</b> (DAS) adalah wilayah daratan yang airnya dialirkan oleh sebuah sungai beserta anak-anak sungainya. Batasnya disebut <b>batas DAS</b> (<i>watershed</i>), yaitu garis punggung bukit yang memisahkannya dari DAS lain. DAS biasanya dibagi menjadi bagian <b>hulu</b> (curam, terutama daerah tangkapan air yang harus dilindungi), bagian <b>tengah</b> dan bagian <b>hilir</b> (landai, tempat sebagian besar penduduk tinggal dan banjir meluas).</p>
⟦0⟧
⟦1⟧
<h3>Debit sungai</h3>
⟦2⟧
⟦3⟧
<p>Waktu jeda yang singkat dan puncak yang tinggi menandakan sungai yang cepat meluap dan berbahaya: khas DAS yang curam, gundul atau banyak permukiman. Hutan, lereng landai dan tanah yang mudah meresapkan air menghasilkan waktu jeda yang panjang dan puncak yang rendah.</p>
⟦4⟧`,
  '2ar3ez5bpun': R`Dendritik`,
  '23nooibpqcw': R`Trellis`,
  '2gkl3419f3x': R`Radial`,
  '29s2kitricg': R`Rektangular`,
  '1ynfb81hxzq': R`Anular`,
  'yljtrbfzq7': R`Sentripetal`,
  '18injy57n5b': R`Paralel`,
  '1qql2txb1eg': R`Tujuh pola aliran sungai: dendritik, trellis, radial, rektangular, anular, sentripetal dan paralel`,
  '1lrv2uyjibk': R`Pola aliran sungai mencerminkan batuan dan bentuk lahan di bawahnya.`,
  '1bt9kag19yt': R`Tempat terbentuk`,
  '1bap1l1l9y5': R`bercabang seperti pohon`,
  'j8dd7twiyv': R`batuan seragam, misalnya dataran`,
  'y0azunfypg': R`sungai utama sejajar dengan anak sungai pendek yang tegak lurus`,
  'p00n167wr2': R`batuan terlipat (punggungan dan lembah)`,
  '1er3vn14u0w': R`mengalir keluar ke segala arah`,
  '1ozu2t1idkx': R`gunung api dan kubah`,
  '4ajujimsww': R`mengalir masuk ke satu titik`,
  'vkv94rpx67': R`cekungan dan kawah`,
  '31fi4wdfe3': R`berbelok tajam membentuk siku`,
  '2d24z0clir8': R`batuan yang terpotong kekar dan sesar`,
  'rzk61wy6qb': R`melingkar`,
  '1emco473xdy': R`kubah tererosi dengan batuan berselang-seling`,
  '1rzd1y4oat8': R`sejajar berdampingan`,
  '27k1cokdb2': R`lereng yang panjang dan rata`,
  '1jcpc7w5y0g': R`<p><b>Debit</b> adalah volume air yang melewati suatu titik setiap detik:</p><p>$$Q = A \times v$$</p><p>dengan $A$ luas penampang sungai (m²) dan $v$ kecepatan rata-rata (m/s), sehingga $Q$ dalam m³/s. Untuk DAS kecil, <b>metode rasional</b> memperkirakan debit puncak banjir: $Q = 0{,}278\,C\,I\,A$ ($Q$ dalam m³/s, intensitas hujan $I$ dalam mm/jam, luas $A$ dalam km²).</p>`,
  'k0p1cei6qw': R`debit`,
  '1spkplu2eu0': R`curah hujan`,
  'sgodbcs31a': R`waktu jeda`,
  'kcf7eiw0ka': R`jam setelah hujan mulai`,
  '74rbx6dg74': R`Hidrograf banjir: hujan lebat sesaat, lalu debit sungai naik ke puncak beberapa jam kemudian dan perlahan turun`,
  '1cn8gw4l7xk': R`Hidrograf banjir. <b>Waktu jeda</b> (lag time) adalah selang antara puncak hujan dan puncak debit.`,
  '2awiacv2upi': R`<p><b>Rezim sungai</b> adalah perubahan debit sungai sepanjang tahun. Sungai-sungai di Indonesia mengikuti musim hujan dan kemarau. Menurut alirannya, sungai dibedakan menjadi sungai <b>permanen</b> (selalu mengalir), <b>periodik</b> (mengalir hanya pada musim hujan) dan <b>episodik</b> (mengalir hanya setelah hujan lebat). Kapuas (1.143 km) adalah sungai terpanjang di Indonesia.</p>`,
  'yxq0k5yjgl': R`Sebuah sungai lebarnya ⟦0⟧ dengan kedalaman rata-rata ⟦1⟧, dan airnya mengalir dengan kecepatan ⟦2⟧. Berapa debitnya?`,
  '1l78qqm75dv': R`$A = ⟦0⟧ \times ⟦1⟧ = ⟦2⟧\,\mathrm{m^2}$, jadi $Q = A v = ⟦3⟧ \times ⟦4⟧ = ⟦5⟧$.`,
  '13az9u9axuq': R`Sebuah sungai mengalirkan ⟦0⟧ melalui penampang seluas ⟦1⟧. Berapa kecepatan aliran rata-ratanya?`,
  '27c15xqyoqe': R`Perkirakan debit puncak banjir dengan metode rasional $Q = 0{,}278\,C\,I\,A$: koefisien limpasan ⟦0⟧, intensitas hujan ⟦1⟧ per jam, luas DAS ⟦2⟧.`,
  '1d9mlb1usnp': R`$Q = 0{,}278 \times ⟦0⟧ \times ⟦1⟧ \times ⟦2⟧ = ⟦3⟧$.`,
  'vtzyu2fqlc': R`Pada hidrograf, hujan mencapai puncak ⟦0⟧ jam setelah mulai dan sungai mencapai puncak ⟦1⟧ jam setelah mulai. Berapa waktu jedanya?⟦2⟧`,
  '11571bzhrro': R`Hidrograf banjir`,
  '2ducj90m2c5': R`Waktu jeda = ⟦0⟧ − ⟦1⟧ = ⟦2⟧.`,
  '20fzpd18tyc': R`Pola aliran apa yang ditunjukkan?⟦0⟧`,
  '24bb836rn4s': R`Pola aliran sungai dilihat dari atas`,
  'ng3e2709gi': R`Ini pola <b>⟦0⟧</b>.`,
  '14kh4zuf0jg': R`Sungai-sungai mengalir keluar ke segala arah dari puncak Gunung Merapi`,
  'bbyrfice0k': R`Sungai-sungai mengalir masuk ke sebuah danau di tengah cekungan`,
  '25t2k6lh5yx': R`Sungai utama di lembah di antara punggungan lipatan yang panjang, dengan anak sungai pendek yang bertemu tegak lurus`,
  '1ji30ikxavp': R`Jaringan sungai bercabang seperti pohon di dataran berbatuan seragam`,
  '1carbjaltl7': R`Sungai-sungai berbelok tajam membentuk siku di sepanjang kekar dan sesar`,
  '1bbra051yqe': R`Pola aliran apakah ini? <i>⟦0⟧</i>`,
  'x2564evbla': R`Itu pola <b>⟦0⟧</b>.`,
  '16iu61g3bml': R`Apa yang dimaksud dengan batas DAS (watershed)?`,
  '1q770r6tdjc': R`Punggung bukit yang memisahkan satu DAS dengan DAS berikutnya`,
  '1gsvrqy6ty': R`Bangunan penyimpan air`,
  '21oog7xxp4z': R`Muara sungai`,
  '2ahonpg23s8': R`Bagian sungai yang paling dalam`,
  '1j7weketct5': R`Hujan yang jatuh di kedua sisi batas DAS mengalir ke sungai yang berbeda.`,
  'ak24xxlz4d': R`Bagian DAS mana yang harus dilindungi sebagai daerah tangkapan air?`,
  'mgxfmqmpbu': R`Bagian hulu`,
  '29762ymjt77': R`Bagian hilir`,
  'zfmpubiyia': R`Muara sungai`,
  'urlvvhagdf': R`Dataran banjir`,
  'ta6iern4w4': R`Hutan di bagian hulu yang curam membuat air meresap serta mencegah erosi dan banjir di hilir.`,
  '1p7zpnlidz8': R`Sebuah sungai hanya mengalir pada musim hujan. Termasuk sungai apa?`,
  '1mccyrplsh4': R`Periodik`,
