  '1fwwkhaw6ss': R`Perubahan apa yang membuat puncak banjir sungai lebih tinggi dan lebih cepat?`,
  'i8sbdczqzb': R`Mengganti hutan dengan jalan dan bangunan`,
  '1d21k89b4tn': R`Menanam pohon di lereng`,
  '1enuwm4ledk': R`Membangun sumur resapan`,
