  '22ucctijspu': R`banyak di Laut Banda dan Pasifik`,
  '1u0sxk54pub': R`<p><b>Salinitas</b> adalah massa garam terlarut dalam satu kilogram air laut, dinyatakan dalam permil (‰). Rata-ratanya sekitar 35‰:</p><p>$$\text{salinitas} = \frac{\text{massa garam (g)}}{\text{massa air laut (kg)}}$$</p><p>Salinitas lebih tinggi di tempat yang penguapannya kuat dan hujannya sedikit (Laut Merah, sekitar 40‰) dan lebih rendah di tempat yang banyak mendapat air tawar dari sungai, hujan atau es yang mencair (Laut Baltik).</p>`,
  'l6l5iaadks': R`<p><b>Arus Lintas Indonesia</b> (ARLINDO) membawa air hangat Samudra Pasifik melalui Selat Makassar dan Laut Banda ke Samudra Hindia: mata rantai penting dalam sirkulasi samudra global. Tekanan di dalam laut bertambah sekitar 1 atmosfer setiap 10 m kedalaman.</p>`,
  '2dvrj0uj0c0': R`Menguapkan ⟦0⟧ air laut menyisakan ⟦1⟧ garam. Berapa salinitasnya, dalam permil (‰)?`,
  '1nj5vfy4rt6': R`$\frac{⟦0⟧\,\mathrm{g}}{⟦1⟧\,\mathrm{kg}} = ⟦2⟧$ g per kg $= ⟦3⟧‰$.`,
  '18ilwkrlbfs': R`Air laut memiliki salinitas ⟦0⟧‰. Berapa gram garam yang terlarut dalam ⟦1⟧ air laut itu?`,
  'nwlyt9g4l2': R`Tekanan di dalam laut bertambah sekitar 1 atmosfer setiap 10 m kedalaman, ditambah 1 atmosfer tekanan udara di permukaan. Berapa tekanan total pada kedalaman ⟦0⟧, dalam atmosfer?`,
