  '219yyb5q6n0': R`Keadaan panas dan kering menguapkan banyak air dan sedikit air tawar yang masuk, sehingga salinitasnya mencapai sekitar 40‰.`,
  'kiwj9t8gg5': R`Mengapa daerah arus dingin sering menjadi daerah perikanan yang baik?`,
