  'mg4pu68suq': R`
<p><b>Pasang surut</b> adalah naik turunnya permukaan laut secara teratur, terutama akibat gaya gravitasi Bulan dan sebagian akibat gravitasi Matahari. Bulan menarik air laut sehingga menggembung di sisi Bumi yang menghadapnya, dan gembungan kedua terbentuk di sisi yang berlawanan. Karena Bumi berotasi, kebanyakan pantai melewati dua gembungan setiap hari: dua kali pasang dan dua kali surut kira-kira setiap 24 jam 50 menit. Selisih tinggi antara pasang dan surut disebut <b>tunggang pasang</b> (tidal range).</p>
⟦0⟧
⟦1⟧
<p>Pantai-pantai Indonesia memiliki tipe pasang surut yang berbeda: <b>harian ganda</b> (dua kali pasang sehari, seperti di Selat Malaka), <b>harian tunggal</b> (sekali sehari, seperti di sebagian Laut Jawa) dan <b>campuran</b>.</p>
<h3>Gelombang</h3>
⟦2⟧
⟦3⟧
⟦4⟧
⟦5⟧`,
  '6cxv9puacv': R`Bulan`,
  'wq568ryws7': R`Pasang purnama: tunggang pasang terbesar`,
  '17htjuuacxn': R`Pasang purnama: Matahari, Bumi dan Bulan segaris, sehingga gembungan pasang paling besar`,
  '25yt5du8dud': R`<b>Pasang purnama</b> saat bulan baru dan bulan purnama: tarikan Matahari dan Bulan segaris, menghasilkan pasang tertinggi dan surut terendah.`,
  '10s0gvqd7o9': R`Pasang perbani: tunggang pasang terkecil`,
  '17zoya3tk5q': R`Pasang perbani: Bulan tegak lurus terhadap Matahari, sehingga gembungan pasang paling kecil`,
  '25n2ey9p89w': R`<b>Pasang perbani</b> saat kuartal pertama dan terakhir: tarikannya saling tegak lurus dan sebagian saling meniadakan, menghasilkan tunggang pasang terkecil.`,
  '2wpsn2d693': R`<p>Gelombang terbentuk oleh angin yang bertiup di atas permukaan air; besarnya bergantung pada kecepatan angin, lamanya angin bertiup dan <b>fetch</b> (panjang laut terbuka yang dilalui angin). Cepat rambat gelombang adalah</p><p>$$v = \frac{\lambda}{T}$$</p><p>dengan $\lambda$ panjang gelombang dan $T$ periode. Gelombang <b>destruktif</b> tinggi dan sering, dengan arus balik (backwash) kuat yang mengikis; gelombang <b>konstruktif</b> rendah, dengan hempasan (swash) kuat yang membangun pantai. Gelombang yang datang miring terhadap pantai memindahkan pasir di sepanjang pantai: <b>arus susur pantai</b> (longshore drift).</p>`,
  '3lfypoz0sh': R`tebing`,
  '1s64ur9jgk3': R`takik`,
  '1ngdowrobps': R`dataran abrasi`,
  '6tmb3h3xgr': R`gua lengkung`,
  '1bxaxhj4eoe': R`stack`,
  '1kzkfy9573v': R`Bentang alam hasil abrasi pantai: tebing dengan takik dan dataran abrasi, gua lengkung dan stack`,
  'iyxfrlmj50': R`<b>Abrasi</b>: gelombang mengikis takik, tebing runtuh dan mundur, meninggalkan dataran abrasi. Gua yang menembus tanjung menjadi gua lengkung (arch), dan ketika lengkungnya runtuh terbentuk stack (seperti Tanah Lot, Bali).`,
  'ht1go5hwir': R`spit`,
  'vrmgmmifqo': R`tombolo`,
  'haihqq24ei': R`pulau`,
  '1gumajwz2v4': R`laguna di balik penghalang`,
  'edcjycslmd': R`gisik`,
  '1r4c773zdjz': R`arus susur pantai`,
  '1rxwz0e1nfg': R`Bentang alam hasil pengendapan pantai dilihat dari atas: gisik, spit, tombolo yang menghubungkan pulau dengan daratan, dan laguna di balik penghalang`,
  '1lif7o3a8k7': R`<b>Pengendapan</b>: pasir membentuk gisik (pantai berpasir); arus susur pantai memanjangkannya menjadi spit; tombolo menghubungkan pulau dengan daratan; penghalang pasir dapat menutup laguna.`,
  'dolsmvwcn5': R`<p><b>Melindungi pantai.</b> Bangunan keras (tembok laut, pemecah gelombang, groin) mahal dan dapat memindahkan abrasi ke tempat lain. <b>Mangrove</b> dan <b>terumbu karang</b> meredam energi gelombang, menangkap sedimen dan menjadi tempat berlindung ikan; Indonesia memiliki sekitar seperlima mangrove dunia.</p>`,
  '1tlddajwzi5': R`Di sebuah pelabuhan, pasang naik mencapai ⟦0⟧ dan surut turun sampai ⟦1⟧ pada papan pengukur pasang surut. Berapa tunggang pasangnya?`,
  '1s4oyywhk0p': R`Tunggang pasang = pasang − surut = $⟦0⟧ - ⟦1⟧ = ⟦2⟧$.`,
  '1vc5fketvd1': R`Gelombang laut memiliki panjang gelombang ⟦0⟧ dan periode ⟦1⟧. Berapa cepat rambatnya?`,
  '1juvudg8elj': R`Tebing lempung yang lunak mundur sekitar ⟦0⟧ per tahun akibat abrasi. Berapa jauh tebing itu mundur dalam ⟦1⟧ tahun?`,
  'wxnj1p340p': R`Perhatikan posisi Matahari, Bumi dan Bulan. Pasang surut jenis apakah ini?⟦0⟧`,
  'rwe226jdpm': R`Matahari, Bumi dan Bulan`,
  'z81n5f90j0': R`Pasang purnama`,
  '1c4xqqk6acz': R`Pasang perbani`,
  'b08xs1rzat': R`Hanya surut`,
  '1p3sd3nw4o6': R`Tidak ada pasang surut`,
  '2auwrta3q98': R`Hanya pasang`,
  '7jzi346oax': R`Matahari, Bumi dan Bulan segaris (bulan baru atau purnama): tarikannya saling menguatkan, menghasilkan <b>pasang purnama</b> dengan tunggang pasang terbesar.`,
  '25vt4bec3m9': R`Bulan tegak lurus terhadap Matahari (bulan kuartal): tarikannya sebagian saling meniadakan, menghasilkan <b>pasang perbani</b> dengan tunggang pasang terkecil.`,
  '1ce4byyzhzf': R`tiang batu yang berdiri di laut, terpisah dari tebing`,
  '1voibq3mo5g': R`Stack`,
  'l8wsc10wto': R`punggungan pasir yang menghubungkan pulau dengan daratan`,
