  'g8n4377794': R`Dataran abrasi`,
  'zj4qbfeilr': R`perairan tenang yang terpisah dari laut oleh penghalang pasir`,
  'xkh10tsokh': R`Laguna`,
  '2bywlxwsxpr': R`Bentang alam pantai apakah ⟦0⟧?`,
  '16o18b2vh9d': R`Apa penyebab utama pasang surut?`,
  '1uxrhy41k2e': R`Gravitasi Bulan, dibantu gravitasi Matahari`,
  '1fxud60cro': R`Gempa bumi di bawah laut`,
  '4pvgji0vgj': R`Perbedaan salinitas`,
  '246t228r7td': R`Tarikan Bulan membentuk gembungan air; tarikan Matahari menambah atau mengurangi gembungan itu.`,
  '1m9cnnuzpxu': R`Kapan pasang purnama terjadi?`,
  '28lcwv1mz3u': R`Saat bulan baru dan bulan purnama`,
  '6rwzw1xfpi': R`Hanya pada musim semi`,
  '13fgyjmhm0t': R`Saat kuartal pertama dan terakhir`,
  '3iwzg43ki4': R`Sekali setahun`,
  '1crcygjhw27': R`Saat bulan baru dan purnama, Matahari, Bumi dan Bulan segaris. Dalam bahasa Inggris disebut "spring tide", tetapi tidak berkaitan dengan musim semi.`,
  '1t9f16hslbp': R`Mengapa mangrove penting bagi pantai?`,
