  '16ocl5uzeft': R`Kepadatan penduduk per kelompok pulau (sekitar 2020, jiwa per km²). Lebih dari separuh penduduk Indonesia tinggal di Jawa, yang luasnya hanya 7% daratan.`,
  '7tvuoy21jj': R`<p><b>Kepadatan penduduk aritmetik</b> = jumlah penduduk ÷ luas wilayah. <b>Kepadatan fisiologis</b> = jumlah penduduk ÷ luas lahan pertanian. <b>Kepadatan agraris</b> = jumlah petani ÷ luas lahan pertanian: kepadatan agraris yang tinggi berarti lahan pertanian sempit dan tekanan terhadap lahan besar, seperti di Jawa.</p>`,
  'pr767xfy4x': R`Sebuah provinsi berpenduduk ⟦0⟧ jiwa dan dalam setahun lahir ⟦1⟧ bayi. Berapa angka kelahiran kasarnya (per 1.000)?`,
  'hn0iioy0os': R`$\text{CBR} = \frac{⟦0⟧}{⟦1⟧} \times 1000 = ⟦2⟧$ per 1.000.`,
  '2ggvohiowdw': R`Sebuah negara memiliki angka kelahiran kasar ⟦0⟧ dan angka kematian kasar ⟦1⟧ per 1.000. Tanpa memperhitungkan migrasi, berapa laju pertumbuhan alaminya dalam persen?`,
  'g37r8zqa4v': R`Sebuah kota berpenduduk ⟦0⟧ ribu jiwa dan tumbuh ⟦1⟧% per tahun. Dengan $P_t = P_0(1 + r)^t$, berapa jumlah penduduknya setelah ⟦2⟧ tahun (dalam ribu)?`,
  '2ce50fcgbzz': R`$P_{⟦0⟧} = ⟦1⟧ \times ⟦2⟧^{⟦3⟧} = ⟦4⟧$ ribu.`,
  '1nuz5v9ulxi': R`Jumlah penduduk tumbuh ⟦0⟧% per tahun. Kira-kira berapa tahun sampai jumlahnya menjadi dua kali lipat?`,
  'iqqewinuix': R`Aturan 70: $\frac{70}{⟦0⟧} \approx ⟦1⟧$ tahun.`,
  '21fnb9yuo2l': R`Sebuah kabupaten seluas ⟦0⟧ berpenduduk ⟦1⟧ jiwa. Berapa kepadatan penduduk aritmetiknya, dalam jiwa per km²?`,
  '2dj81ii1zpk': R`Sebuah kabupaten berpenduduk ⟦0⟧ jiwa dan memiliki lahan pertanian seluas ⟦1⟧. Berapa kepadatan fisiologisnya, dalam jiwa per km²?`,
