  '1bmmzlqw7to': R`Jepang`,
  '1upccf2jec3': R`<p><b>Rasio jenis kelamin</b> = jumlah laki-laki per 100 perempuan:</p><p>$$SR = \frac{M}{F} \times 100$$</p><p><b>Rasio ketergantungan</b> = jumlah penduduk usia muda dan tua yang harus ditanggung setiap 100 penduduk usia produktif:</p><p>$$DR = \frac{P_{0\text{–}14} + P_{65+}}{P_{15\text{–}64}} \times 100$$</p>`,
  '1mz9gpxrd6p': R`<p>Jika rasio ketergantungan turun di bawah sekitar 50, suatu negara mendapat <b>bonus demografi</b>: banyak tenaga kerja dan relatif sedikit tanggungan. Indonesia berada dalam masa ini kira-kira dari 2012 sampai 2035. Bonus ini baru bermanfaat jika tenaga kerjanya sehat, terdidik dan memiliki pekerjaan.</p>`,
