  'f3u19ad6qs': R`Dari ⟦0⟧ penduduk, ⟦1⟧% berusia 0–14, ⟦2⟧% berusia 15–64 dan ⟦3⟧% berusia 65 tahun ke atas. Berapa rasio ketergantungannya?`,
