  '1nz9obca8zf': R`Sebuah kota memiliki ⟦0⟧ penduduk berusia 0–14, ⟦1⟧ berusia 15–64 dan ⟦2⟧ berusia 65 tahun ke atas. Hitunglah rasio ketergantungannya.`,
