  '1hhuyk67ef9': R`<p><b>Pertumbuhan alami</b> dalam persen adalah $\frac{\text{CBR} - \text{CDR}}{10}$, dengan kedua angka per 1.000. Indonesia (CBR sekitar 16, CDR sekitar 7) berada di akhir <b>tahap 3</b>. Jepang dan Italia berada di tahap 5; Niger dan Chad masih di tahap 2.</p>`,
  '2g4147u6qie': R`<p><b>Kebijakan kependudukan.</b> Program <i>Keluarga Berencana</i> (KB) Indonesia, yang dijalankan BKKBN sejak 1970, menurunkan rata-rata jumlah anak per perempuan (<b>angka kelahiran total</b>, TFR) dari sekitar 5,6 menjadi sekitar 2,2. Negara-negara di tahap 5, seperti Jepang dan Korea Selatan, kini justru memberi tunjangan agar keluarga memiliki lebih banyak anak.</p>`,
