  '22xy49xp8ek': R`Sebuah negara memiliki angka kelahiran kasar ⟦0⟧ dan angka kematian kasar ⟦1⟧ per 1.000. Kemungkinan besar negara itu berada di tahap transisi demografi yang mana?⟦2⟧`,
