  'mtb9ywapva': R`Dalam setahun terdapat ⟦0⟧ kelahiran hidup di sebuah kabupaten dan ⟦1⟧ bayi di antaranya meninggal sebelum berusia satu tahun. Berapa angka kematian bayinya (per 1.000 kelahiran hidup)?`,
