  '1jy0nxko0hp': R`<p><b>Berapa lama akan bertahan?</b> Untuk sumber daya tak terbarukan,</p><p>$$\text{sisa tahun} = \frac{\text{cadangan}}{\text{produksi per tahun}}$$</p><p><b>Rasio cadangan terhadap produksi</b> ini menganggap produksi tetap; penemuan baru memperpanjangnya dan kebutuhan yang meningkat memperpendeknya.</p>`,
