  '2fnrns1tsg5': R`jarak dari kota →`,
  '1ixbleulpgc': R`Cincin von Thünen di sekitar kota, dengan grafik sewa lahan terhadap jarak untuk setiap penggunaan lahan: garis paling curam untuk hasil yang mudah rusak di dekat kota, garis lebih landai untuk penggunaan lahan yang lebih jauh`,
  'd7lbpcf4dh': R`Cincin von Thünen. Setiap penggunaan lahan mampu membayar sewa tertinggi di cincinnya sendiri.`,
  '164astxxcn3': R`<p>Johann Heinrich von Thünen (1826) membayangkan sebuah kota terpencil di dataran yang datar dan seragam. Petani harus membayar ongkos angkut ke pasar, sehingga <b>sewa lahan</b> yang mampu dibayar suatu tanaman berkurang seiring jarak:</p><p>$$R = Y(p - c) - Y f d$$</p><p>dengan $Y$ hasil per hektare, $p$ harga pasar, $c$ biaya produksi, $f$ ongkos angkut per ton per km dan $d$ jarak. Barang yang mudah rusak atau berat (susu, sayuran, dan pada masanya kayu bakar) dihasilkan di dekat kota; biji-bijian dan ternak lebih jauh.</p>`,
  '25qnp2mntgx': R`<p><b>Produktivitas</b> = hasil ÷ luas lahan (ton per hektare). Produktivitas padi Indonesia sekitar 5 t/ha. Ketahanan pangan berarti setiap orang selalu memiliki pangan yang cukup, aman dan bergizi: diperlukan produksi yang cukup, distribusi yang baik dan harga yang terjangkau.</p>`,
  'gj3syrejke': R`Dengan rumus von Thünen $R = Y(p - c) - Y f d$, tentukan sewa lahan per hektare untuk tanaman dengan hasil ⟦0⟧, harga ⟦1⟧ dan biaya produksi ⟦2⟧ per ton, serta ongkos angkut ⟦3⟧ per ton per km, yang ditanam ⟦4⟧ dari pasar.`,
  '7vhqt2j0ur': R`Suatu tanaman menghasilkan ⟦0⟧, dijual ⟦1⟧ per ton dan biaya menanamnya ⟦2⟧ per ton. Ongkos angkutnya ⟦3⟧ per ton per km. Pada jarak lebih dari berapa menanamnya sama sekali tidak menghasilkan sewa?`,
  '1goorsqrqtz': R`Sewa bernilai nol jika $p - c = f d$: $d = \frac{⟦0⟧ - ⟦1⟧}{⟦2⟧} = ⟦3⟧$.`,
  '1g0kywu2h5t': R`Seorang petani memanen ⟦0⟧ padi dari lahan seluas ⟦1⟧. Berapa produktivitasnya?`,
  '1r8he83tdbj': R`Susu segar dan sayuran yang cepat busuk`,
