  '1h7s5jyw6ml': R`jalan dan fasilitas baik, mata pencaharian beragam, hubungan erat dengan kota`,
  '9u02o2nwna': R`Zona konsentris (Burgess)`,
  '27vq7xdl6f7': R`Sektoral (Hoyt)`,
  '685bkg0ut7': R`Inti ganda (Harris dan Ullman)`,
  '2enatwd8n9l': R`1 pusat kegiatan bisnis (CBD); 2 zona peralihan dan industri ringan; 3 permukiman berpendapatan rendah; 4 permukiman berpendapatan menengah; 5 permukiman berpendapatan tinggi atau zona penglaju; 6 industri berat; 7 pusat bisnis pinggiran; 8 permukiman pinggiran; 9 industri pinggiran.`,
  'cs9hiceq5': R`<p><b>Burgess</b> (1925) melihat kota tumbuh ke luar dalam cincin-cincin dari CBD, dengan penduduk terkaya tinggal paling jauh. <b>Hoyt</b> (1939) mencatat bahwa penggunaan lahan meluas dalam <b>sektor-sektor</b> di sepanjang jalan dan rel kereta. <b>Harris dan Ullman</b> (1945) menunjukkan bahwa kota besar tumbuh di sekitar <b>beberapa inti</b>: pusat lama, kawasan industri, pelabuhan, universitas. Kota-kota besar Indonesia seperti Jakarta paling sesuai dengan model inti ganda.</p>`,
  '1wvn59tlb6f': R`<p>Desa dan kota saling bergantung: desa memasok pangan, bahan baku dan tenaga kerja; kota memasok barang industri, jasa, lapangan kerja dan pasar. <b>Daerah pinggiran kota</b> (rural–urban fringe) memadukan keduanya dan berubah cepat ketika lahan pertanian berubah menjadi perumahan (suburbanisasi).</p>`,
  'hrx06kfx5d': R`Memanjang`,
