  '97a0rp8aow': R`Tersebar`,
  '187e6f29d6h': R`Melingkar`,
  'qgugojsqsx': R`Pola permukiman apa yang ditunjukkan?⟦0⟧`,
  '9mxvkxcs22': R`Sebuah desa dilihat dari atas`,
