  'ljg3dbun8g': R`Cenderung perdesaan`,
  'bjgrqm3b5z': R`Cenderung perkotaan`,
  '1n63djdu816': R`Di suatu permukiman berpenduduk ⟦0⟧ jiwa, ⟦1⟧% pekerjanya adalah petani. Apakah sifatnya cenderung perdesaan atau perkotaan?`,
  'ez08opw2xy': R`Sebagian besar penduduk bekerja di pertanian: bersifat perdesaan.`,
