  'wcnntcahfo': R`CBD memiliki harga lahan tertinggi, kantor, toko dan bank, serta aksesibilitas terbaik.`,
  '13pro7wg0kk': R`Menurut model Burgess, di mana penduduk terkaya tinggal?`,
