  '1qelje36hrd': R`Daerah pinggiran adalah tempat kota dan desa bertemu dan penggunaan lahan berubah paling cepat.`,
  '1tyvclsouv7': R`Mengapa Jakarta sesuai dengan model inti ganda?`,
  'lai87m4tvv': R`Jakarta tumbuh di sekitar beberapa pusat: kota tua, pelabuhan, kawasan bisnis dan kawasan industri`,
