  '1f5merg3lq0': R`Zona waktu mengikuti meridian: setiap 15° bujur sama dengan satu jam.`,
  '5ihedaj25g': R`Proyeksi memindahkan jaring-jaring garis lintang dan bujur ke peta datar.`,
  '10tqte8vlss': R`Setiap proyeksi menyimpangkan skala di bagian tertentu peta.`,
